DELETE FROM tb_survey_response
WHERE response_id = #{responseId}
AND updated_at <= DATE_SUB(NOW(), INTERVAL 1 MONTH)

DELETE FROM tb_survey_response
 WHERE survey_id IN (
   SELECT s.survey_id FROM tb_survey s
    WHERE s.delete_yn = 'Y'
      AND s.updated_at <= #{cutoff}
 )

mapper.select:
SELECT COUNT(*) FROM tb_survey_response r
 WHERE r.survey_id IN (
   SELECT s.survey_id FROM tb_survey s
    WHERE s.delete_yn = 'Y'
      AND s.updated_at <= #{cutoff}
 )
